package com.github.tartaricacid.touhoulittlemaid.item;
import com.github.tartaricacid.touhoulittlemaid.TouhouLittleMaid;import com.github.tartaricacid.touhoulittlemaid.entity.item.EntityMaidPainting;import net.minecraft.creativetab.CreativeTabs;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.item.Item;import net.minecraft.item.ItemStack;import net.minecraft.util.Direction;import net.minecraft.world.World;
public final class ItemMaidPainting extends Item{public ItemMaidPainting(){setUnlocalizedName(TouhouLittleMaid.MOD_ID+".wine_fox_painting");setTextureName("minecraft:painting");setCreativeTab(CreativeTabs.tabDecorations);}public boolean onItemUse(ItemStack stack,EntityPlayer player,World world,int x,int y,int z,int side,float hx,float hy,float hz){if(side<2||!player.canPlayerEdit(x,y,z,side,stack))return false;int direction=Direction.facingToDirection[side];EntityMaidPainting painting=new EntityMaidPainting(world,x,y,z,direction);if(painting.onValidSurface()){if(!world.isRemote)world.spawnEntityInWorld(painting);if(!player.capabilities.isCreativeMode)--stack.stackSize;}return true;}}
